package com.sahyog.datacollection.service.impl;
import com.sahyog.datacollection.dto.person.*;
import com.sahyog.datacollection.service.PersonInformationService;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import java.util.regex.Pattern;
@Service
public class PersonInformationServiceImpl implements PersonInformationService {
 private static final String SUMMARY="DC004",DETAILS="DC005"; private static final Pattern NUMBER=Pattern.compile("[AD]\\d{7}"); private final JdbcTemplate jdbc;
 public PersonInformationServiceImpl(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override @Transactional(readOnly=true) public PersonSummaryInitializeResponse initializeSummary(PersonSummaryInitializeRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);List<PersonSummaryItem> rows=jdbc.query("SELECT PERSON_ID,PERSON_TYPE,FIRST_NAME,LAST_NAME,AGE,GENDER FROM DC_PERSON WHERE APPLICATION_NO=? ORDER BY PERSON_ID",(s,n)->new PersonSummaryItem(s.getLong("PERSON_ID"),s.getString("PERSON_TYPE"),s.getString("FIRST_NAME"),s.getString("LAST_NAME"),s.getInt("AGE"),s.getString("GENDER")),c);return new PersonSummaryInitializeResponse(c,SUMMARY,rows,!rows.isEmpty());}
 @Override public PersonSummaryNavigationResponse summaryNext(PersonSummaryNavigationRequest r){return summaryNav(validateNav(r),"DC006",null,null);}
 @Override public PersonSummaryNavigationResponse summaryPrevious(PersonSummaryNavigationRequest r){return summaryNav(validateNav(r),"DC003",null,null);}
 @Override public PersonSummaryNavigationResponse addNew(PersonSummaryNavigationRequest r){return summaryNav(validateNav(r),DETAILS,"ADD",null);}
 @Override @Transactional(readOnly=true) public PersonSummaryNavigationResponse edit(PersonRowRequest r){validateRow(r);String c=resolve(r.appOrCaseNum());ensurePerson(c,r.personId());return summaryNav(c,DETAILS,"EDIT",r.personId());}
 @Override @Transactional public PersonDeleteResponse delete(PersonRowRequest r){validateRow(r);String c=resolve(r.appOrCaseNum());int n=jdbc.update("DELETE FROM DC_PERSON WHERE APPLICATION_NO=? AND PERSON_ID=?",c,r.personId());if(n==0)throw notFound(r.personId());return new PersonDeleteResponse(c,r.personId(),"DELETED");}
 @Override @Transactional(readOnly=true) public PersonInitializeResponse initialize(PersonInitializeRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);if(r.personId()==null)return new PersonInitializeResponse(c,DETAILS,null,false);List<PersonDetails> rows=jdbc.query("SELECT PERSON_ID,PERSON_TYPE,FIRST_NAME,MIDDLE_NAME,LAST_NAME,DATE_OF_BIRTH,AGE,GENDER,CASTE,RELIGION,MARITAL_STATUS,AADHAR_NUMBER,PAN_NUMBER,PASSPORT_NUMBER,RELATIONSHIP_TO_PRIMARY_APPLICANT,IS_LEGAL_DEPENDENT,RESIDES_IN_APPLICANT_HOUSEHOLD,GUARDIAN_PERSON_ID FROM DC_PERSON WHERE APPLICATION_NO=? AND PERSON_ID=?",(s,n)->new PersonDetails(s.getLong("PERSON_ID"),s.getString("PERSON_TYPE"),s.getString("FIRST_NAME"),s.getString("MIDDLE_NAME"),s.getString("LAST_NAME"),s.getObject("DATE_OF_BIRTH",LocalDate.class),s.getInt("AGE"),s.getString("GENDER"),s.getString("CASTE"),s.getString("RELIGION"),s.getString("MARITAL_STATUS"),s.getString("AADHAR_NUMBER"),s.getString("PAN_NUMBER"),s.getString("PASSPORT_NUMBER"),s.getString("RELATIONSHIP_TO_PRIMARY_APPLICANT"),nullableBoolean(s,"IS_LEGAL_DEPENDENT"),nullableBoolean(s,"RESIDES_IN_APPLICANT_HOUSEHOLD"),s.getObject("GUARDIAN_PERSON_ID",Long.class)),c,r.personId());if(rows.isEmpty())throw notFound(r.personId());return new PersonInitializeResponse(c,DETAILS,rows.get(0),true);}
 @Override @Transactional public PersonNavigationResponse next(PersonSaveRequest r){String c=save(r);return new PersonNavigationResponse(c,"IN_PROGRESS",DETAILS,"DC006");}
 @Override @Transactional public PersonNavigationResponse previous(PersonSaveRequest r){String c=save(r);return new PersonNavigationResponse(c,"IN_PROGRESS",DETAILS,SUMMARY);}
 private String save(PersonSaveRequest r){validate(r);String c=resolve(r.appOrCaseNum());ensureApplication(c);PersonDetails p=r.person();int age=Period.between(p.dob(),LocalDate.now()).getYears();String rel=normalize(p.relationshipToPrimaryApplicant());if(p.personId()==null){jdbc.update("INSERT INTO DC_PERSON (APPLICATION_NO,PERSON_TYPE,FIRST_NAME,MIDDLE_NAME,LAST_NAME,DATE_OF_BIRTH,AGE,GENDER,CASTE,RELIGION,MARITAL_STATUS,AADHAR_NUMBER,PAN_NUMBER,PASSPORT_NUMBER,RELATIONSHIP_TO_PRIMARY_APPLICANT,IS_LEGAL_DEPENDENT,RESIDES_IN_APPLICANT_HOUSEHOLD,GUARDIAN_PERSON_ID) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",c,p.personType().trim(),p.firstName().trim(),trim(p.middleName()),p.lastName().trim(),p.dob(),age,p.gender().trim(),trim(p.casteRace()),trim(p.religion()),trim(p.maritalStatus()),p.aadharNumber().trim(),trim(p.panNumber()),trim(p.passportNumber()),rel,p.isLegalDependent(),p.residesInApplicantHousehold(),p.guardianPersonId());}else{int n=jdbc.update("UPDATE DC_PERSON SET PERSON_TYPE=?,FIRST_NAME=?,MIDDLE_NAME=?,LAST_NAME=?,DATE_OF_BIRTH=?,AGE=?,GENDER=?,CASTE=?,RELIGION=?,MARITAL_STATUS=?,AADHAR_NUMBER=?,PAN_NUMBER=?,PASSPORT_NUMBER=?,RELATIONSHIP_TO_PRIMARY_APPLICANT=?,IS_LEGAL_DEPENDENT=?,RESIDES_IN_APPLICANT_HOUSEHOLD=?,GUARDIAN_PERSON_ID=? WHERE APPLICATION_NO=? AND PERSON_ID=?",p.personType().trim(),p.firstName().trim(),trim(p.middleName()),p.lastName().trim(),p.dob(),age,p.gender().trim(),trim(p.casteRace()),trim(p.religion()),trim(p.maritalStatus()),p.aadharNumber().trim(),trim(p.panNumber()),trim(p.passportNumber()),rel,p.isLegalDependent(),p.residesInApplicantHousehold(),p.guardianPersonId(),c,p.personId());if(n==0)throw notFound(p.personId());}jdbc.update("UPDATE DC_APPLICATION SET PAGE_ID=?,APPLICATION_STATUS='IN_PROGRESS',UPDATED_DATE=CURRENT_TIMESTAMP WHERE APPLICATION_NO=?",DETAILS,c);return c;}
 private void validate(PersonSaveRequest r){if(r==null||r.person()==null)throw bad("person is required");resolve(r.appOrCaseNum());PersonDetails p=r.person();if(blank(p.personType())||blank(p.firstName())||blank(p.lastName())||p.dob()==null||blank(p.gender())||blank(p.aadharNumber()))throw bad("personType, firstName, lastName, dob, gender, and aadharNumber are required");if(p.dob().isAfter(LocalDate.now()))throw bad("dob cannot be in the future");if(!p.aadharNumber().trim().matches("\\d{12}"))throw bad("aadharNumber must contain exactly 12 digits");if(!blank(p.relationshipToPrimaryApplicant())&&!Set.of("SELF","SPOUSE","CHILD","PARENT","SIBLING","LEGAL_DEPENDENT","OTHER").contains(normalize(p.relationshipToPrimaryApplicant())))throw bad("invalid relationshipToPrimaryApplicant");}
 private String validateNav(PersonSummaryNavigationRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);return c;} private void validateRow(PersonRowRequest r){if(r==null||r.personId()==null)throw bad("personId is required");}
 private void ensureApplication(String c){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM DC_APPLICATION WHERE APPLICATION_NO=?",Integer.class,c);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Data collection application not found: "+c);} private void ensurePerson(String c,Long id){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM DC_PERSON WHERE APPLICATION_NO=? AND PERSON_ID=?",Integer.class,c,id);if(n==null||n==0)throw notFound(id);}
 private String resolve(String v){String n=v==null?"":v.trim().toUpperCase(Locale.ROOT);if(!NUMBER.matcher(n).matches())throw bad("appOrCaseNum must match A or D followed by 7 digits");return n.startsWith("A")?"D"+n.substring(1):n;} private PersonSummaryNavigationResponse summaryNav(String c,String d,String m,Long id){return new PersonSummaryNavigationResponse(c,SUMMARY,d,m,id);} private String normalize(String v){return blank(v)?null:v.trim().toUpperCase(Locale.ROOT);} private String trim(String v){return blank(v)?null:v.trim();}private boolean blank(String v){return v==null||v.isBlank();}private Boolean nullableBoolean(java.sql.ResultSet s,String column)throws java.sql.SQLException{boolean v=s.getBoolean(column);return s.wasNull()?null:v;}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException notFound(Long id){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Person record not found: "+id);}
}
